const clean = (v) => String(v || '').trim().replace(/^<|>$/g, '');
const stripHtml = (html) => String(html || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim();

const messages = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const meta = j.metadata || {};
  const uid = j.attributes && j.attributes.uid ? String(j.attributes.uid) : '';

  const messageId = clean(meta['message-id'] || j['message-id'] || '') || `imap-${uid || Date.now()}`;
  const references = String(meta.references || j.references || '').match(/<[^>]+>/g) || [];
  const inReplyTo = clean(meta['in-reply-to'] || j['in-reply-to'] || '');
  const threadId = references.length ? clean(references[0]) : (inReplyTo || messageId);

  const recipients = [j.to, j.cc]
    .filter(Boolean)
    .join(',')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);

  const parsed = new Date(j.date || meta.date || Date.now());
  const receivedAt = Number.isNaN(parsed.getTime()) ? new Date().toISOString() : parsed.toISOString();
  const bodyText = j.textPlain ? String(j.textPlain) : stripHtml(j.textHtml || j.text || '');

  messages.push({ json: {
    gmailMessageId: messageId.slice(0, 255),
    gmailThreadId: threadId.slice(0, 255),
    sender: String(j.from || meta.from || '').slice(0, 500),
    recipients,
    subject: String(j.subject || '(sans objet)').slice(0, 1000),
    bodyText: bodyText.slice(0, 400000),
    receivedAt
  } });
}

return messages.filter((m) => m.json.gmailMessageId && m.json.sender);

const messages = $input.all().map((item) => item.json).filter((m) => m.gmailMessageId);
if (messages.length === 0) return [];

const CHUNK = 50;
const cursorEnd = String(Math.floor(Date.now() / 1000));
const chunks = [];
for (let i = 0; i < messages.length; i += CHUNK) {
  chunks.push({ json: {
    mailbox: $env.MAILBOX_ADDRESS,
    cursor: null,
    executionId: $execution.id,
    messages: messages.slice(i, i + CHUNK),
    _cursorEnd: cursorEnd
  } });
}
return chunks;

const responses = $input.all();
let imported = 0;
let skipped = 0;
for (const r of responses) {
  const d = (r.json && r.json.data) || {};
  imported += Number(d.imported || 0);
  skipped += Number(d.skipped || 0);
}
const first = $('Découper en lots').first().json;
return [{ json: {
  mailbox: $env.MAILBOX_ADDRESS,
  executionId: $execution.id,
  status: 'SUCCESS',
  cursorStart: null,
  cursorEnd: first._cursorEnd || null,
  importedCount: imported,
  updatedCount: 0,
  skippedCount: skipped,
  failedCount: 0
} }];
